/*
 * Firstwish shared contracts: one shape per registry resource and one request and response per registry endpoint.
 * Generated by tools/pipeline/gen_schema.py from the frozen .pipeline/registry.json. Types only: no runtime imports, so the
 * web app can use contracts/firstwish-contracts.d.ts (npm run contracts:export) without importing the API.
 */

/** A UUIDv7 id issued by the server. */
export type Id = string;
/** An instant on the wire: ISO-8601 UTC ("2026-11-15T14:30:00.000Z"). */
export type Instant = string;
/** A calendar date: "YYYY-MM-DD" (ruling C-29). */
export type DateOnly = string;
/** A whole number of kobo (NGN). Never a float, never a formatted string. */
export type Kobo = number;
export type Currency = "NGN";
/** Money on the wire where a field carries amount and currency together. */
export interface Money {
  amount: Kobo;
  currency: Currency;
}
/** Every list: ?cursor=&limit= (1 to 50, default 20). */
export interface PaginatedList<T> {
  items: T[];
  nextCursor: string | null;
}
export interface ListQuery {
  cursor?: string;
  limit?: number;
}
/** Every error. */
export interface ErrorEnvelope {
  error: { code: string; message: string; fields?: Record<string, string>; requestId: string };
}
/** A response with no body fields. */
export type Empty = Record<string, never>;
/** 204 No Content: an endpoint whose registry response is null answers with no body (Q12). */
export type NoContent = void;
/** What every payment start returns about the payment it opened (Q12, DEC-139). */
export interface PaymentStart {
  reference: string;
  state: Payment["status"];
  amountKobo: Kobo;
  /** The provider's checkout page the payer goes to. */
  authorizationUrl: string;
}
/** A payment start: the payment, beside what it buys (null until the verified payment fulfils it). */
export interface PaymentStarted<T> {
  payment: PaymentStart;
  item: T | null;
}
/** A start that may cost nothing (E-228: the Pass covers the keep): payment is null then. */
export interface PaymentStartedOrCovered<T> {
  payment: PaymentStart | null;
  item: T | null;
}

/** One earning line of the numbers page (FB2): the key staff set targets by, the words staff read, and the kobo earned. */
export interface NumbersLine {
  line: NumbersTarget["line"];
  name: string;
  definition: string;
  amount: Kobo;
}
/** E-5. */
export interface HandleCheck {
  free: boolean;
  problem?: string;
}
/** E-57, E-58. */
export interface FollowResponse {
  handle: string;
  following: boolean;
}
/** E-155, E-156. */
export interface SaveResponse {
  saved: boolean;
  counts: Record<string, number>;
}
/** E-142, E-143. */
export interface ReactResponse {
  reaction: Reaction | null;
  counts: { reactions: number; saves: number };
}
/** E-166. */
export interface ShareResponse {
  url: string;
  title: string;
  text: string;
}
/** E-60: the invoice file. */
export interface InvoiceFile {
  name: string;
  type: "text/html";
  text: string;
}
/** E-171, E-172. */
export interface ShootFilesAdded {
  shoot: Shoot;
  added: number;
  previews: number;
}
/** E-132 (LL2, DEC-182): the reaction as kept and how many of each reaction the wish holds. Never the sender's wish. */
export interface ReactionResult {
  reaction: string;
  counts: Record<string, number>;
}
/**
 * E-134 (LL2, DEC-182): ok with a token (and when it stops working) once a passcode or an answer was right; an unprotected wish
 * answers ok alone. The page sends the token back in the x-unlock-token header.
 */
export type UnlockResult = { ok: true; token?: string; expiresAt?: Instant } | { ok: false; error: string };
/** E-15, E-16 (shape in the registry note of E-15). */
export interface StyleChange {
  base?: string;
  theme?: unknown;
  scenes?: Record<string, unknown>;
  made?: unknown;
  tags?: unknown;
  ops?: unknown[];
  said: string[];
  credits: number;
}
/** E-20, E-53, E-159 (T1, DEC-150): a sign-in or a refresh. The refresh token is only in the httpOnly cookie. */
export interface AuthResult {
  /** The access token the web app keeps in memory only (R10). */
  accessToken: string;
  accessExpiresAt: Instant;
  /** true when this sign-in made the account (the web app shows Welcome). */
  isNew: boolean;
  session: { id: Id; expiresAt: Instant };
  /** E-53 only: the path the Google sign-in started from. */
  returnTo?: string;
}
/** E-176, E-234 (S5, DEC-148): a staff sign-in or a staff refresh. The refresh token is only in the httpOnly staff cookie. */
export interface StaffAuthResult {
  staff: StaffAccount;
  accessToken: string;
  accessTokenExpiresAt: Instant;
}
/** E-54 (T2, DEC-151): where the browser goes to sign in with Google. */
export interface GoogleStart {
  url: string;
}
/** A read that returns every row in ONE answer, no paging (X28, DEC-166): nextCursor is always null. */
export interface AllList<T> {
  items: T[];
  nextCursor: null;
}
/** UploadTicket.upload (X20, DEC-163): the signed PUT. It binds the content type and length (X26). */
export interface SignedUpload {
  url: string;
  method: "PUT";
  headers: Record<string, string>;
  expiresAt: Instant;
}
/** One priced line of a quote (X13, DEC-160). */
export interface QuoteLine {
  sku: string;
  name: string;
  qty: number;
  /** The list price of one. */
  listKobo: Kobo;
  /** The price charged for one at the quote's moment. */
  unitKobo: Kobo;
  /** unitKobo times qty. */
  totalKobo: Kobo;
  discounted: boolean;
}
/** E-213 (X13, DEC-160): ONE quote for a ticket and its extras, priced by the server from the price book. */
export interface TicketQuote {
  /** The price-book version the quote used. */
  version: number;
  versionId: Id;
  lines: QuoteLine[];
  totalKobo: Kobo;
  listTotalKobo: Kobo;
}
/** E-125 (X14, DEC-161): the public price book, paged by ?cursor=&limit=. */
export interface PriceBook {
  version: number;
  items: Price[];
  promotion: Promotion | null;
  lifecycle: LifecycleConfig | null;
  entitlements: Entitlements;
  nextCursor: string | null;
}
/** E-225 (CC1, DEC-170): a saved draft: the version to send with the next write, and when this one landed. */
export interface WishSaved {
  version: number;
  updatedAt: Instant;
}
/** One row an import left out (BB8, DEC-169): its position in the pasted rows (1 is the first) and why. */
export interface PeopleImportSkipped {
  row: number;
  reason: string;
  /** the field that was refused (API-BASE-6) */
  field?: string;
}
/** E-121 (BB8, DEC-169): how many people were added and which rows were skipped. */
export interface PeopleImportResult {
  added: number;
  skipped: PeopleImportSkipped[];
  /** HR5: one entry for every row sent, in order: accepted, or refused with the field and the words; a person twice is a duplicate */
  rows: PeopleImportRow[];
}
/** HR5: what became of one row of an import. */
export interface PeopleImportRow {
  row: number;
  state: "accepted" | "refused" | "duplicate";
  /** the field that was refused: name, birthday, start, phone or row */
  field?: string;
  reason?: string;
}
/** E-19: the registry names the response SignInCode and gives no fields. */
export type SignInCode = Record<string, unknown>;
/** E-202 (DEC-65): a read view of a live StudioStyle with its submission. */
export type SubmittedStyle = StudioStyle & { submission?: StyleSubmission | null };
/** A support thread with its messages: what E-207, E-208, E-209 and the contact page answer (YY3). */
export type ThreadDetail = SupportThread & { messages: SupportMessage[] };
/** E-133 without a code: the code was mailed, nothing is filed yet (QQ1). */
export interface TakeDownSent {
  sent: true;
  expiresAt: Instant;
}
export type TakeDownResult = Report | TakeDownSent;
/** What the creator's earnings list carries beside the page (WW7). */
export interface RoyaltySummary {
  thisMonthKobo: Kobo;
  waitingKobo: Kobo;
  sendingKobo: Kobo;
  paidKobo: Kobo;
  byStyle: { styleSlug: string; amountKobo: Kobo }[];
}
/** E-154: the creator's accruals and reversals, newest first, with the summary (WW7). */
export interface RoyaltyEarnings extends PaginatedList<RoyaltyAccrual> {
  summary: RoyaltySummary;
}

/** Account: table. written by E-3, E-7, E-9, E-11 and server:sessions; the person's account (sessions declaration Me); erase really removes personal fields, so name, contact (the email, S-27), phone, bio and handle are nullable in storage */
export interface Account {
  action: "ban" | "lift" | "erase";
  /** HR3 (E-6, E-7): the business the person owns and every business they are a login of, owner first: id, name, role and the login's state */
  businesses?: Array<{ id: string; name: string; role: "owner" | "login"; state: "owner" | "invited" | "active" | "removed" }>;
  ban?: Record<string, unknown> | null;
  bio?: string | null;
  business: string;
  contact: string;
  creator: boolean;
  dates: unknown[];
  email: string;
  erased: boolean;
  handle: string;
  here: string;
  id: string;
  joined: string;
  lastSide: string;
  mode: "light" | "dark" | "system";
  name: string;
  pass?: { active: boolean; endsAt: Instant } | null;
  phone: string;
  pro?: Record<string, unknown> | null;
  reason: string;
  record: unknown[];
  side: unknown;
  sides: Array<"person" | "creator" | "business">;
  space?: "me" | "business" | "creator" | null;
  timeZone?: string | null;
  wishCount: number;
  wishes: unknown[];
}

